package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.RefreshTokenMaxLifetimeSecondsVO;

class RefreshTokenMaxLifetimeSecondsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of refresh token max lifetime seconds of tenant config")
  void test_refresh_token_max_lifetime_seconds_value_holder_assign_plain_value() {
    Object holder = new Object();
    RefreshTokenMaxLifetimeSecondsValueHolder<Object> value =
        new RefreshTokenMaxLifetimeSecondsValueHolder<>(holder);
    Assertions.assertSame(holder, value.refreshTokenMaxLifetimeSeconds(1),
        "Setters must return the holder");
    Assertions.assertTrue(value.getRefreshTokenMaxLifetimeSecondsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getRefreshTokenMaxLifetimeSeconds().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of refresh token max lifetime seconds of tenant config")
  void test_refresh_token_max_lifetime_seconds_value_holder_assign_value_object() {
    Object holder = new Object();
    RefreshTokenMaxLifetimeSecondsValueHolder<Object> value =
        new RefreshTokenMaxLifetimeSecondsValueHolder<>(holder);
    RefreshTokenMaxLifetimeSecondsVO vo = RefreshTokenMaxLifetimeSecondsVO.from(1);
    Assertions.assertFalse(value.getRefreshTokenMaxLifetimeSecondsValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.refreshTokenMaxLifetimeSeconds(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getRefreshTokenMaxLifetimeSecondsValue().orElseThrow());
    Assertions.assertSame(holder, value.refreshTokenMaxLifetimeSeconds(Optional.empty()));
    Assertions.assertFalse(value.getRefreshTokenMaxLifetimeSecondsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.refreshTokenMaxLifetimeSeconds(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRefreshTokenMaxLifetimeSecondsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of refresh token max lifetime seconds of tenant config against the original")
  void test_refresh_token_max_lifetime_seconds_value_holder_read() {
    Object holder = new Object();
    RefreshTokenMaxLifetimeSecondsValueHolder<Object> value =
        new RefreshTokenMaxLifetimeSecondsValueHolder<>(holder);
    RefreshTokenMaxLifetimeSecondsVO vo = RefreshTokenMaxLifetimeSecondsVO.from(1);
    RefreshTokenMaxLifetimeSecondsVO other = RefreshTokenMaxLifetimeSecondsVO.from(1);
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getRefreshTokenMaxLifetimeSecondsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other,
        value.readRefreshTokenMaxLifetimeSeconds(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRefreshTokenMaxLifetimeSeconds(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.refreshTokenMaxLifetimeSeconds(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo,
        value.readRefreshTokenMaxLifetimeSeconds(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRefreshTokenMaxLifetimeSeconds(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of refresh token max lifetime seconds of tenant config")
  void test_refresh_token_max_lifetime_seconds_value_holder_unset() {
    Object holder = new Object();
    RefreshTokenMaxLifetimeSecondsValueHolder<Object> value =
        new RefreshTokenMaxLifetimeSecondsValueHolder<>(holder);
    RefreshTokenMaxLifetimeSecondsVO vo = RefreshTokenMaxLifetimeSecondsVO.from(1);
    value.refreshTokenMaxLifetimeSeconds(vo);
    Assertions.assertSame(holder,
        value.unsetRefreshTokenMaxLifetimeSecondsIfMatches("refreshTokenMaxLifetimeSeconds_other"));
    Assertions.assertTrue(value.getRefreshTokenMaxLifetimeSecondsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetRefreshTokenMaxLifetimeSecondsIfMatches("refreshTokenMaxLifetimeSeconds"));
    Assertions.assertFalse(value.getRefreshTokenMaxLifetimeSecondsValue().isPresent(),
        "The field name must clear the value");
    value.refreshTokenMaxLifetimeSeconds(vo);
    Assertions.assertSame(holder, value.unsetRefreshTokenMaxLifetimeSeconds());
    Assertions.assertFalse(value.getRefreshTokenMaxLifetimeSecondsValue().isPresent(),
        "Unset must clear the value");
  }
}
